    compute_bfs(start_x, start_y);
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> grid2[a][b];
            if ('1' <= grid2[a][b] && grid2[a][b] <= '9') {
                addEdge(n * n + a * n + b, sink, grid2[a][b] - '0');
            }
        }
    }
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            if ('1' <= grid1[a][b] && grid1[a][b] <= '9') {
                explore_bfs(a, b);
            }
        }
    }
    cout << compute_max_flow(source, sink) << "\n";
    return 0;
