import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 0x3f3f3f3f;
    static final int MAXN = 20;
    static final int MAXV = 2 * MAXN * MAXN;

    static char[][] grid1 = new char[MAXN][MAXN];
    static char[][] grid2 = new char[MAXN][MAXN];
    static int[][] dist_time = new int[MAXN][MAXN];
    static int n, t;

    static int[] directions = {1, 0, -1, 0};
    static int[] directionsY = {0, 1, 0, -1};

    static List<Integer>[] adj_list = new ArrayList[MAXV];
    static int[][] capacity = new int[MAXV][MAXV];

    static int[] time_grid = new int[MAXN][MAXN];
    static boolean[] visited_nodes = new boolean[MAXV];
    static int[] level = new int[MAXV];

    static int start_x, start_y;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXV; i++) {
            adj_list[i] = new ArrayList<>();
        }

        int source = MAXV - 2;
        int sink = MAXV - 1;

        for (int a = 0; a < n; a++) {
            String line = br.readLine();
            for (int b = 0; b < n; b++) {
                grid1[a][b] = line.charAt(b);
                if (grid1[a][b] == 'Z') {
                    start_x = a;
                    start_y = b;
                } else if (grid1[a][b] >= '1' && grid1[a][b] <= '9') {
                    addEdge(source, a * n + b, grid1[a][b] - '0');
                }
            }
        }

        compute_bfs(start_x, start_y);

        for (int a = 0; a < n; a++) {
            String line = br.readLine();
            for (int b = 0; b < n; b++) {
                grid2[a][b] = line.charAt(b);
                if (grid2[a][b] >= '1' && grid2[a][b] <= '9') {
                    addEdge(n * n + a * n + b, sink, grid2[a][b] - '0');
                }
            }
        }

        for (int a = 0; a < n; a++) {
            for (int b = 0; b < n; b++) {
                if (grid1[a][b] >= '1' && grid1[a][b] <= '9') {
                    explore_bfs(a, b);
                }
            }
        }

        System.out.println(compute_max_flow(source, sink));
    }

    static void compute_bfs(int startX, int startY) {
        for (int i = 0; i < n; ++i)
            Arrays.fill(dist_time[i], INF);
        dist_time[startX][startY] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{startX, startY});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            for (int dir = 0; dir < 4; ++dir) {
                int nx = x + directions[dir], ny = y + directionsY[dir];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if ('0' <= grid1[nx][ny] && grid1[nx][ny] <= '9' && dist_time[nx][ny] == INF) {
                    dist_time[nx][ny] = dist_time[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static void addEdge(int u, int v, int c) {
        adj_list[u].add(v);
        adj_list[v].add(u);
        capacity[u][v] = c;
        capacity[v][u] = 0;
    }

    static boolean build_level_graph(int s, int t) {
        Arrays.fill(level, -1);
        level[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty() && level[t] == -1) {
            int v = q.poll();
            for (int nxt : adj_list[v]) {
                if (capacity[v][nxt] == 0 || level[nxt] != -1) continue;
                level[nxt] = level[v] + 1;
                q.offer(nxt);
            }
        }
        return level[t] != -1;
    }

    static void explore_bfs(int px, int py) {
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(time_grid[i], INF);
        }
        time_grid[px][py] = 0;
        if (grid2[px][py] >= '1' && grid2[px][py] <= '9') {
            addEdge(n * px + py, n * n + n * px + py, INF);
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{px, py});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            for (int dir = 0; dir < 4; ++dir) {
                int nx = x + directions[dir], ny = y + directionsY[dir];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if (time_grid[nx][ny] != INF) continue;
                if (!(grid1[nx][ny] >= '0' && grid1[nx][ny] <= '9')) continue;
                if (time_grid[x][y] + 1 <= Math.min(dist_time[nx][ny] - 1, t)) {
                    time_grid[nx][ny] = time_grid[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
                if (time_grid[x][y] + 1 <= Math.min(dist_time[nx][ny], t) && grid2[nx][ny] >= '1' && grid2[nx][ny] <= '9') {
                    addEdge(n * px + py, n * n + nx * n + ny, INF);
                }
            }
        }
    }

    static int compute_max_flow(int s, int t) {
        int total_flow = 0, flow;
        while (build_level_graph(s, t)) {
            Arrays.fill(visited_nodes, false);
            while ((flow = dinic_search(s, t, INF)) > 0) {
                total_flow += flow;
                Arrays.fill(visited_nodes, false);
            }
        }
        return total_flow;
    }

    static int dinic_search(int v, int t, int flow) {
        if (v == t) return flow;
        visited_nodes[v] = true;
        for (int nxt : adj_list[v]) {
            if (capacity[v][nxt] == 0 || visited_nodes[nxt] || level[nxt] != level[v] + 1) continue;
            int pushed = dinic_search(nxt, t, Math.min(flow, capacity[v][nxt]));
            if (pushed > 0) {
                capacity[v][nxt] -= pushed;
                capacity[nxt][v] += pushed;
                return pushed;
            }
        }
        return 0;
    }
}
